from datetime import datetime

class InMemoryStore:
    def __init__(self):
        self.saved = []

    def save(self, record: dict) -> None:
        self.saved.append(record)

class AttendanceService:
    def __init__(self, store, clock):
        self.store, self.clock = store, clock

    def check_in(self, employee: str) -> str:
        now = self.clock()
        status = "late" if now.hour >= 10 else "on time"
        self.store.save({"employee": employee, "at": now.strftime("%H:%M"), "status": status})
        return f"{employee} is {status}"

