def standard(kg: float) -> float:
    return 40 + 20 * kg

def express(kg: float) -> float:
    return 99 + 35 * kg

SHIPPING = {"standard": standard, "express": express}

def quote(kg: float, method: str) -> float:
    if method not in SHIPPING:
        raise ValueError(f"unknown shipping method: {method}")
    return SHIPPING[method](kg)

