class EventBus:
    def __init__(self):
        self.handlers = {}

    def subscribe(self, event, handler):
        self.handlers.setdefault(event, []).append(handler)

        def unsubscribe():
            self.handlers[event].remove(handler)

        return unsubscribe

    def publish(self, event, payload) -> int:
        handlers = list(self.handlers.get(event, []))
        for handler in handlers:
            handler(payload)
        return len(handlers)

bus = EventBus()
stop = bus.subscribe("price_drop", lambda item: print("alert:", item))
print(bus.publish("price_drop", "Brass Kettle"))
